mapper.select:
SELECT p.id, p.project_type, p.project_name, p.project_intro, p.innovation_points, p.project_background, p.project_significance, p.market_demand_analysis, p.key_technology, p.plan_file_path, p.plan_file_name, p.status, p.applicant_id, p.applicant_name, p.auditor_name, p.reject_reason, p.project_space, p.create_time, p.update_time, p.submit_time, u.college as applicant_college FROM project p LEFT JOIN user u ON p.applicant_id = u.id
AND p.project_name LIKE CONCAT('%', #{projectName}, '%')
AND p.project_type = #{projectType}
AND p.status = #{status}
AND p.project_space LIKE CONCAT('%', #{projectSpace}, '%')
AND p.applicant_id = #{applicantId}
ORDER BY p.create_time DESC
